package by.bsuir.workorder; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.scheduling.annotation.EnableScheduling;
@EnableScheduling @SpringBootApplication(scanBasePackages="by.bsuir") public class WorkOrderApplication {public static void main(String[]a){SpringApplication.run(WorkOrderApplication.class,a);}@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(x->x.anyRequest().permitAll()).build();}}
